window.PB_LEGAL_DOCS = {"updated":"25 de noviembre de 2026","fields":[{"k":"titular","label":"Nombre completo o razón social","opt":false},{"k":"nit","label":"NIT o identificación","opt":false},{"k":"direccion","label":"Dirección y ciudad (domicilio)","opt":false},{"k":"correo_oficial","label":"Correo electrónico oficial","opt":false},{"k":"inventario_cookies","label":"Inventario de cookies (nombre, proveedor, finalidad, duración, categoría)","opt":false},{"k":"correo_privacidad","label":"Correo de privacidad y protección de datos","opt":false},{"k":"cargo_datos","label":"Cargo o nombre de quien atiende datos personales","opt":false},{"k":"fecha_vigencia","label":"Fecha de entrada en vigencia de la política de PQRS","opt":false},{"k":"formulario_habilitado","label":"Formulario habilitado para derechos de datos (opcional)","opt":true},{"k":"enlace_preferencias","label":"Enlace o mecanismo de preferencias de cookies (opcional)","opt":true},{"k":"nota_inventario","label":"Texto sobre el inventario de cookies (opcional)","opt":true},{"k":"form_pqrs","label":"Enlace del formulario PQRS","opt":false},{"k":"correo_atencion","label":"Correo de atención (PQRS)","opt":false},{"k":"horario","label":"Días y horario de atención","opt":false},{"k":"nota_radicacion","label":"Texto sobre cómo se radica y consulta una solicitud (opcional)","opt":true},{"k":"nota_compromiso","label":"Compromiso operativo (opcional)","opt":true},{"k":"canal_seguridad","label":"Canal para reportes de seguridad","opt":false}],"docs":{"quienes":{"title":"Quiénes somos","blocks":[{"p":["Ofertas Bogotá es una plataforma digital creada para conectar a los consumidores con los negocios, emprendimientos, productos y servicios de Bogotá y la Sabana."]},{"p":["Nacemos con el propósito de fortalecer el comercio local, facilitar la visibilidad digital de los emprendedores y brindar herramientas publicitarias y tecnológicas accesibles para negocios de diferentes tamaños."]},{"p":["Buscamos construir un espacio donde las personas puedan descubrir nuevas oportunidades comerciales y donde los negocios puedan promocionar sus productos y servicios de manera sencilla, organizada y cercana."]},{"h":"Misión"},{"p":["Impulsar el crecimiento y la transformación digital de los negocios locales mediante soluciones accesibles de publicidad, diseño gráfico y desarrollo web, facilitando la conexión entre comerciantes y consumidores."]},{"h":"Visión"},{"p":["Consolidarnos como una plataforma digital de referencia para el comercio local en Bogotá y la Sabana, reconocida por su innovación, transparencia, accesibilidad y compromiso con los emprendedores, con proyección de expansión a otras regiones de Colombia."]},{"h":"Nuestros valores"},{"ul":[[{"b":"Transparencia:"}," brindar información clara sobre nuestros servicios y condiciones comerciales."],[{"b":"Compromiso:"}," trabajar por el fortalecimiento de los negocios locales."],[{"b":"Innovación:"}," desarrollar soluciones digitales que respondan a las necesidades del mercado."],[{"b":"Accesibilidad:"}," ofrecer alternativas al alcance de pequeños y medianos emprendimientos."],[{"b":"Responsabilidad:"}," actuar de manera ética y respetuosa."],[{"b":"Confianza:"}," construir relaciones comerciales basadas en la honestidad."],[{"b":"Cercanía:"}," brindar atención personalizada a nuestros clientes."]]},{"h":"Nuestros servicios"},{"p":[{"b":"Publicidad digital:"}," publicación de anuncios, promociones, productos y servicios dentro de nuestra plataforma, facilitando su búsqueda por ubicación y categoría."]},{"p":[{"b":"Diseño gráfico y publicitario:"}," creación de piezas gráficas, contenido promocional, identidad visual y material publicitario digital."]},{"p":[{"b":"Desarrollo de páginas web:"}," creación de soluciones web adaptadas a las necesidades de negocios, profesionales y emprendimientos."]},{"h":"Nuestro propósito"},{"p":["Creemos que todos los negocios, independientemente de su tamaño, merecen una oportunidad para ser visibles en el mundo digital."]},{"p":[{"b":"Ofertas Bogotá --- La vitrina digital de los negocios, productos y servicios de Bogotá y la Sabana."}]}]},"terminos":{"title":"Términos y condiciones","blocks":[{"p":[{"b":"Ofertas Bogotá"}]},{"p":[{"b":"Sitio web:"}," www.ofertasbogota.lat"]},{"p":[{"b":"Última actualización:"}," 25 de noviembre de 2026"]},{"p":[{"b":"País de operación:"}," Colombia"]},{"p":[{"b":"Titular responsable:"}," ",{"k":"titular"}]},{"p":[{"b":"Identificación o NIT:"}," ",{"k":"nit"}]},{"p":[{"b":"Domicilio y dirección de notificaciones:"}," ",{"k":"direccion"}]},{"p":[{"b":"Correo electrónico:"}," ",{"k":"correo_oficial"}]},{"p":[{"b":"WhatsApp:"}," 310 798 7275"]},{"h":"1. Objeto y aceptación"},{"p":["Los presentes términos y condiciones regulan el acceso, navegación, registro, utilización y contratación de los servicios ofrecidos por Ofertas Bogotá."]},{"p":["Al utilizar la plataforma o contratar nuestros servicios, el usuario acepta las condiciones aplicables, sin perjuicio de los derechos irrenunciables reconocidos por la legislación colombiana."]},{"h":"2. Naturaleza de la plataforma"},{"p":["Ofertas Bogotá es una plataforma digital de publicidad, promoción comercial y prestación de servicios tecnológicos."]},{"p":["Su finalidad es facilitar la conexión entre consumidores, comerciantes, emprendedores y prestadores de servicios."]},{"p":["Salvo cuando Ofertas Bogotá sea directamente el proveedor del servicio contratado, la plataforma no actúa como vendedor, fabricante, distribuidor ni intermediario financiero de los productos anunciados por terceros."]},{"p":["Ofertas Bogotá es una iniciativa privada e independiente y no pertenece a ninguna entidad gubernamental."]},{"h":"3. Ámbito de operación"},{"p":["La plataforma está dirigida principalmente a negocios y consumidores ubicados en Bogotá y municipios de la Sabana, incluyendo Chía, Soacha, Mosquera, Funza, Cota y Zipaquirá."]},{"p":["Ofertas Bogotá podrá ampliar su cobertura geográfica según sus capacidades operativas y comerciales."]},{"h":"4. Tipos de usuarios"},{"p":["La plataforma contempla las siguientes categorías:"]},{"ul":[["Visitantes: personas que consultan información pública."],["Usuarios registrados: personas que cuentan con una cuenta dentro de la plataforma."],["Anunciantes: negocios o personas que publican productos, servicios o promociones."],["Clientes: personas naturales o jurídicas que contratan servicios directamente con Ofertas Bogotá."],["Administradores: personal autorizado para gestionar y supervisar la plataforma."]]},{"h":"5. Registro y creación de cuentas"},{"p":["Para acceder a determinadas funcionalidades, el usuario deberá crear una cuenta proporcionando información verdadera, actualizada y verificable."]},{"p":["Los titulares de cuentas deberán ser mayores de 18 años o actuar mediante un representante legal autorizado cuando corresponda."]},{"p":["El usuario será responsable de:"]},{"ul":[["Mantener la confidencialidad de sus credenciales."],["Utilizar contraseñas seguras."],["Actualizar su información de contacto."],["Informar cualquier acceso no autorizado."],["No compartir ni comercializar sus credenciales de acceso."],["No utilizar identidades falsas ni suplantar a terceros."]]},{"p":["Ofertas Bogotá adoptará medidas razonables de seguridad para proteger las cuentas y la información bajo su responsabilidad."]},{"h":"6. Panel privado del cliente"},{"p":["Los clientes registrados podrán acceder a un panel privado para administrar las funcionalidades disponibles según el servicio contratado."]},{"p":["Estas podrán incluir:"]},{"ul":[["Gestión de anuncios y promociones."],["Administración del perfil comercial."],["Consulta de estadísticas."],["Gestión de planes y servicios."],["Historial de pagos y facturación."],["Notificaciones."],["Actualización de datos."],["Configuración de seguridad."],["Solicitudes de soporte."]]},{"p":["La disponibilidad de cada funcionalidad dependerá del estado de desarrollo de la plataforma y del plan contratado."]},{"h":"7. Servicios de publicidad digital"},{"p":["Ofertas Bogotá ofrece espacios digitales destinados a promocionar negocios, productos, servicios y ofertas comerciales."]},{"p":["Las condiciones de cada espacio publicitario podrán variar según:"]},{"ul":[["Tamaño y ubicación del anuncio."],["Duración de la publicación."],["Categoría comercial."],["Cobertura geográfica."],["Disponibilidad de espacios."],["Características del plan contratado."]]},{"p":["La contratación de publicidad no garantiza una cantidad determinada de ventas, clientes, visitas, contactos o ingresos económicos."]},{"h":"8. Promoción especial de lanzamiento"},{"p":["Con motivo del lanzamiento de Ofertas Bogotá, programado para el 1 de diciembre de 2026, se ofrecerá publicidad gratuita hasta el 31 de enero de 2027, inclusive."]},{"p":["Esta promoción estará sujeta a las siguientes condiciones:"]},{"ul":[["Cumplimiento de las políticas de publicación."],["Disponibilidad de espacios publicitarios."],["Entrega de información y material requerido."],["Revisión y aprobación de los anuncios."],["Ausencia de contenido ilegal, engañoso o prohibido."]]},{"p":["La promoción aplica exclusivamente a los espacios publicitarios incluidos en la campaña de lanzamiento."]},{"p":["Los servicios de diseño gráfico, desarrollo web y demás servicios adicionales no se encuentran incluidos, salvo indicación expresa."]},{"p":["Una vez finalizada la promoción, el cliente podrá decidir si desea contratar un plan de pago."]},{"p":["No se realizarán cobros automáticos por la finalización del periodo gratuito sin autorización previa y expresa del cliente."]},{"h":"9. Planes publicitarios y vigencia"},{"p":["Los planes publicitarios tendrán las características, precios, beneficios y periodos de vigencia informados antes de su contratación."]},{"p":["Salvo acuerdo expreso, los planes no tendrán cláusulas de permanencia mínima ni renovación automática."]},{"p":["Una vez finalizado el periodo contratado, los anuncios podrán quedar inactivos hasta que el cliente solicite su renovación."]},{"p":["Los cambios de precios no afectarán retroactivamente los periodos previamente contratados."]},{"h":"10. Publicación y revisión de anuncios"},{"p":["Ofertas Bogotá podrá revisar los anuncios antes o después de su publicación con el propósito de verificar el cumplimiento de las condiciones de uso."]},{"p":["El anunciante será responsable de proporcionar información comercial clara y veraz, incluyendo precios, características, disponibilidad y condiciones de sus promociones."]},{"p":["La aprobación de un anuncio no constituye una certificación de calidad, legalidad, solvencia o cumplimiento comercial del anunciante."]},{"p":["Ofertas Bogotá podrá solicitar correcciones o retirar publicaciones que incumplan las condiciones establecidas."]},{"h":"11. Responsabilidad de los anunciantes"},{"p":["Cada anunciante será responsable de:"]},{"ul":[["La autenticidad de sus productos y servicios."],["Los precios y descuentos publicados."],["La disponibilidad de los productos anunciados."],["El cumplimiento de las promociones."],["Las garantías legales aplicables."],["La entrega de productos y servicios."],["La atención de sus consumidores."],["El cumplimiento de sus obligaciones tributarias y comerciales."],["Contar con los permisos y autorizaciones requeridos para su actividad."]]},{"p":["Los anunciantes deberán respetar la legislación colombiana y los derechos de los consumidores."]},{"h":"12. Productos, servicios y contenidos prohibidos"},{"p":["No se permitirá la publicación de contenido relacionado con:"]},{"ul":[["Productos o servicios ilegales."],["Sustancias ilícitas."],["Armas y productos cuya comercialización no esté autorizada."],["Estafas, fraudes o esquemas piramidales."],["Productos falsificados o de procedencia ilícita."],["Explotación sexual o contenido sexual ilícito."],["Discriminación, amenazas o incitación a la violencia."],["Publicidad engañosa."],["Suplantación de identidad."],["Vulneración de derechos de propiedad intelectual."],["Distribución de software malicioso."],["Actividades que comprometan la seguridad de los usuarios."]]},{"p":["Ofertas Bogotá podrá restringir categorías comerciales adicionales cuando existan razones legales, operativas o de seguridad debidamente justificadas."]},{"h":"13. Servicios de diseño gráfico"},{"p":["Ofertas Bogotá podrá prestar servicios de creación y edición de material gráfico, incluyendo:"]},{"ul":[["Diseños publicitarios."],["Piezas para redes sociales."],["Banners."],["Logotipos e identidad visual."],["Material promocional."],["Contenido gráfico digital."]]},{"p":["Antes de iniciar el servicio se informará al cliente sobre el precio, alcance, formato de entrega, plazo estimado y cantidad de modificaciones incluidas."]},{"p":["Las modificaciones adicionales o los cambios sustanciales al alcance aprobado podrán generar costos adicionales, previa aceptación del cliente."]},{"p":["Los archivos editables o fuentes de diseño únicamente estarán incluidos cuando así se establezca en la cotización."]},{"p":["El cliente deberá contar con autorización para utilizar las imágenes, logotipos y demás materiales que suministre."]},{"h":"14. Servicios de desarrollo web"},{"p":["Ofertas Bogotá podrá ofrecer servicios de creación, configuración y desarrollo de páginas web."]},{"p":["Cada proyecto contará con una cotización o acuerdo que podrá establecer:"]},{"ul":[["Alcance del desarrollo."],["Funcionalidades incluidas."],["Número de páginas o secciones."],["Tecnologías utilizadas."],["Diseño y personalización."],["Plazos estimados."],["Condiciones de pago."],["Dominio y alojamiento."],["Mantenimiento y soporte."],["Entrega de archivos y credenciales."],["Derechos de uso y propiedad intelectual."]]},{"p":["Los servicios de alojamiento, dominio, licencias, mantenimiento, integraciones externas y actualizaciones posteriores podrán tener costos independientes, previamente informados."]},{"p":["Ofertas Bogotá no garantiza posiciones específicas en buscadores, cantidades de visitas ni resultados comerciales derivados del sitio desarrollado."]},{"h":"15. Dominios y alojamiento web"},{"p":["Cuando el servicio incluya la adquisición o administración de dominios y alojamiento, se informará al cliente sobre:"]},{"ul":[["Titularidad del dominio."],["Proveedor contratado."],["Periodo de vigencia."],["Costos de renovación."],["Condiciones de transferencia."],["Responsabilidades de administración."]]},{"p":["La titularidad de los dominios adquiridos para clientes deberá quedar definida en el acuerdo correspondiente."]},{"p":["Los servicios de terceros estarán sujetos también a las condiciones de sus respectivos proveedores."]},{"h":"16. Cotizaciones y contratación"},{"p":["Las cotizaciones deberán indicar las características esenciales del servicio, su precio total, impuestos aplicables, condiciones de pago, vigencia y plazos estimados."]},{"p":["El servicio podrá formalizarse mediante aceptación escrita, contratación electrónica u otro mecanismo que permita acreditar la voluntad del cliente."]},{"p":["Los cambios posteriores deberán ser acordados por ambas partes."]},{"h":"17. Precios y medios de pago"},{"p":["Los precios serán expresados en pesos colombianos (COP), indicando los impuestos y costos adicionales aplicables."]},{"p":["Ofertas Bogotá podrá habilitar diferentes medios de pago, incluyendo:"]},{"ul":[["Transferencias bancarias."],["Nequi."],["DaviPlata."],["Bre-B."],["Pasarelas de pago autorizadas."]]},{"p":["El cliente deberá verificar que los datos de pago correspondan a los canales oficiales informados por Ofertas Bogotá."]},{"p":["Los anticipos, pagos parciales y saldos pendientes serán definidos antes de la contratación."]},{"p":["Se entregarán los comprobantes o documentos de facturación que correspondan conforme a las obligaciones legales aplicables."]},{"h":"18. Cancelaciones, devoluciones y derecho de retracto"},{"p":["Las solicitudes de cancelación o devolución serán evaluadas según la naturaleza del servicio, su estado de ejecución y la legislación colombiana."]},{"p":["Cuando resulte aplicable el derecho de retracto, el consumidor podrá ejercerlo dentro de los cinco días hábiles establecidos legalmente, contados desde el momento correspondiente según la naturaleza del contrato."]},{"p":["Las excepciones legales, incluyendo determinados servicios cuya ejecución haya comenzado con autorización del consumidor, serán aplicadas únicamente cuando se cumplan los requisitos previstos en la ley."]},{"p":["Los servicios personalizados, anticipos y trabajos parcialmente ejecutados estarán sujetos a las condiciones acordadas y a los derechos legales del consumidor."]},{"p":["Ninguna disposición de estos términos podrá interpretarse como una renuncia a los derechos de retracto, garantía, devolución o reversión del pago cuando legalmente procedan."]},{"h":"19. Entrega y aprobación de servicios"},{"p":["Los plazos de entrega serán informados antes de iniciar cada proyecto."]},{"p":["Cuando el desarrollo dependa de información, materiales o aprobaciones del cliente, los retrasos atribuibles a su entrega podrán modificar el cronograma, previa comunicación."]},{"p":["El cliente podrá revisar los entregables y solicitar las correcciones comprendidas en el alcance contratado."]},{"p":["La aprobación de un trabajo no elimina las garantías legales aplicables."]},{"h":"20. Propiedad intelectual"},{"p":["La marca, identidad visual, logotipo, diseños propios, estructura y contenidos originales de Ofertas Bogotá se encuentran protegidos conforme a la legislación aplicable."]},{"p":["Los usuarios no podrán reproducir, distribuir, modificar o explotar comercialmente dichos elementos sin autorización."]},{"p":["Los anunciantes conservarán los derechos sobre los contenidos propios que suministren y autorizan a Ofertas Bogotá a utilizarlos para ejecutar el servicio publicitario contratado."]},{"p":["La utilización de estos materiales para portafolios o campañas propias ajenas al servicio requerirá autorización cuando corresponda."]},{"p":["Los derechos sobre diseños y desarrollos personalizados se establecerán en cada acuerdo, respetando las normas colombianas sobre propiedad intelectual y derechos de autor."]},{"h":"21. Estadísticas y métricas"},{"p":["Ofertas Bogotá podrá proporcionar información relacionada con:"]},{"ul":[["Visualizaciones de anuncios."],["Clics."],["Interacciones."],["Visitas a perfiles comerciales."],["Rendimiento publicitario."],["Clics en canales de contacto."]]},{"p":["Estas métricas podrán presentar variaciones por filtros automatizados, bloqueadores, errores técnicos o métodos de medición."]},{"p":["Un clic en un canal de contacto no implica necesariamente que se haya producido una conversación, una venta o una contratación."]},{"p":["Las estadísticas tienen carácter informativo y no constituyen garantías de resultados económicos."]},{"h":"22. Relación entre consumidores y anunciantes"},{"p":["Las operaciones comerciales realizadas directamente entre consumidores y anunciantes serán responsabilidad de las partes que intervengan en ellas, sin perjuicio de las obligaciones legales que correspondan a Ofertas Bogotá por su participación efectiva."]},{"p":["Se recomienda a los consumidores verificar la identidad del negocio, las condiciones de compra, los medios de pago y las garantías ofrecidas."]},{"p":["Ofertas Bogotá podrá recibir reportes sobre comportamientos fraudulentos, publicidad engañosa o incumplimientos comerciales y adoptar las medidas correspondientes dentro de sus competencias."]},{"h":"23. Seguridad informática"},{"p":["Ofertas Bogotá implementará medidas técnicas y organizativas razonables para proteger la plataforma y la información bajo su responsabilidad."]},{"p":["Está prohibido:"]},{"ul":[["Acceder sin autorización a cuentas o sistemas."],["Intentar vulnerar mecanismos de autenticación."],["Realizar ataques informáticos."],["Introducir código malicioso."],["Extraer datos personales sin autorización."],["Manipular estadísticas o generar tráfico artificial."],["Interferir con el funcionamiento de la plataforma."]]},{"p":["Los incidentes de seguridad podrán ser investigados y reportados a las autoridades competentes cuando corresponda."]},{"h":"24. Disponibilidad de la plataforma"},{"p":["Ofertas Bogotá procurará mantener la disponibilidad y funcionamiento adecuado de sus servicios."]},{"p":["Sin embargo, podrán presentarse interrupciones por mantenimiento, actualizaciones, incidentes técnicos, fallas de proveedores o circunstancias de fuerza mayor."]},{"p":["Cuando una interrupción afecte un servicio contratado, se evaluarán las medidas de solución, compensación o devolución que correspondan conforme al contrato y la legislación aplicable."]},{"h":"25. Suspensión y cancelación de cuentas"},{"p":["Ofertas Bogotá podrá suspender temporalmente o cancelar cuentas cuando se identifiquen:"]},{"ul":[["Incumplimientos graves de estos términos."],["Actividades fraudulentas."],["Suplantación de identidad."],["Incumplimientos de pago."],["Publicaciones ilegales."],["Amenazas a la seguridad."],["Uso indebido de la plataforma."]]},{"p":["Cuando sea posible, se informará al usuario sobre las razones de la medida y los canales disponibles para solicitar su revisión."]},{"p":["Las medidas inmediatas podrán aplicarse cuando exista un riesgo urgente para la seguridad, los usuarios o el cumplimiento legal."]},{"h":"26. Protección de datos personales"},{"p":["El tratamiento de datos personales se realizará conforme a la Ley 1581 de 2012, sus normas reglamentarias y demás disposiciones aplicables."]},{"p":["Los datos podrán utilizarse para gestionar cuentas, prestar servicios, procesar solicitudes, administrar pagos, garantizar la seguridad y cumplir obligaciones legales."]},{"p":["Los usuarios podrán ejercer sus derechos de conocimiento, actualización, rectificación, supresión y revocación de la autorización cuando corresponda."]},{"p":["La autorización para recibir comunicaciones comerciales deberá gestionarse conforme a la legislación aplicable."]},{"p":["El tratamiento detallado de la información estará regulado por la Política de Tratamiento de Datos Personales de Ofertas Bogotá."]},{"h":"27. Comunicaciones y notificaciones"},{"p":["Ofertas Bogotá podrá enviar comunicaciones relacionadas con:"]},{"ul":[["Estado de los servicios."],["Vencimientos de planes."],["Pagos y facturación."],["Cambios en los anuncios."],["Seguridad de las cuentas."],["Actualizaciones relevantes."],["Solicitudes de soporte."]]},{"p":["Las comunicaciones promocionales serán enviadas conforme a las autorizaciones otorgadas y a las disposiciones legales aplicables."]},{"p":["El usuario podrá solicitar dejar de recibir publicidad sin afectar las comunicaciones necesarias para la prestación de los servicios."]},{"h":"28. Peticiones, quejas, reclamos y sugerencias"},{"p":["Los usuarios podrán presentar solicitudes, reclamaciones, reportes y sugerencias mediante los canales oficiales de atención."]},{"p":[{"b":"Sitio web:"}," www.ofertasbogota.lat"]},{"p":[{"b":"WhatsApp:"}," 310 798 7275"]},{"p":[{"b":"Correo electrónico:"}," ",{"k":"correo_oficial"}]},{"p":["Las solicitudes serán atendidas dentro de los plazos establecidos por la legislación aplicable."]},{"p":["Ofertas Bogotá procurará ofrecer mecanismos que permitan consultar el estado de las solicitudes y conservar constancia de su recepción."]},{"h":"29. Limitación de responsabilidad"},{"p":["Ofertas Bogotá responderá por sus obligaciones contractuales y legales."]},{"p":["No será responsable por hechos exclusivamente atribuibles a terceros, información falsa suministrada por anunciantes o circunstancias ajenas a su control, cuando legalmente corresponda."]},{"p":["Esta disposición no excluye ni limita las responsabilidades obligatorias establecidas por la legislación colombiana."]},{"h":"30. Modificaciones de los términos y condiciones"},{"p":["Ofertas Bogotá podrá actualizar estos términos para incorporar cambios legales, técnicos, comerciales u operativos."]},{"p":["Las modificaciones serán publicadas indicando su fecha de actualización."]},{"p":["Los cambios que afecten condiciones esenciales de servicios previamente contratados requerirán la aceptación correspondiente cuando legalmente proceda."]},{"h":"31. Legislación aplicable"},{"p":["Los presentes términos se interpretarán conforme a la legislación de la República de Colombia, incluyendo las normas aplicables sobre:"]},{"ul":[["Protección al consumidor."],["Comercio electrónico."],["Protección de datos personales."],["Propiedad intelectual."],["Derechos de autor."],["Contratación electrónica."],["Seguridad informática."]]},{"p":["Las controversias podrán gestionarse mediante mecanismos de atención directa, conciliación o ante las autoridades competentes, respetando los derechos de los consumidores."]},{"h":"32. Canales oficiales"},{"p":[{"b":"Marca:"}," Ofertas Bogotá"]},{"p":[{"b":"Página web:"}," www.ofertasbogota.lat"]},{"p":[{"b":"Instagram:"}," @ofertasbogo"]},{"p":[{"b":"WhatsApp:"}," 310 798 7275"]},{"p":[{"b":"Cobertura:"}," Bogotá y la Sabana, Colombia."]},{"p":["Ofertas Bogotá promueve relaciones comerciales responsables, transparentes y respetuosas, con el propósito de contribuir al fortalecimiento del comercio local."]},{"p":["Inventario de cookies y tecnologías similares (nombre, proveedor, finalidad, duración y categoría): ",{"k":"inventario_cookies"}]}]},"privacidad":{"title":"Política de privacidad","blocks":[{"h":"1. Objeto y alcance"},{"p":["Ofertas Bogotá reconoce la importancia de proteger la privacidad de las personas que visitan www.ofertasbogota.lat, crean una cuenta, anuncian sus negocios o contratan servicios de publicidad, diseño gráfico y desarrollo web. Esta política explica qué información puede recopilarse, cómo se utiliza, con quién puede compartirse y qué opciones tiene el usuario para controlar su información."]},{"p":["La política se aplica a los canales digitales administrados por Ofertas Bogotá, incluidos los formularios, el panel privado del cliente y los canales oficiales de atención. Se complementa con la Política de Tratamiento de Datos Personales y no sustituye las autorizaciones exigidas por la legislación colombiana."]},{"h":"2. Identificación del responsable"},{"p":["El responsable del tratamiento es ",{"k":"titular"},", identificado con ",{"k":"nit"},", con domicilio en ",{"k":"direccion"},". Las solicitudes relacionadas con privacidad podrán remitirse a ",{"k":"correo_privacidad"}," o a través del WhatsApp 310 798 7275."]},{"h":"3. Información que podemos recopilar"},{"p":["La información solicitada dependerá de la relación del usuario con la plataforma y de las funcionalidades efectivamente habilitadas. Se procurará limitar la recolección a los datos necesarios para cada finalidad."]},{"ul":[["Datos de identificación y contacto: nombre, correo electrónico, teléfono y, cuando sea necesario para contratar o facturar, identificación y dirección."],["Información comercial: nombre del negocio, actividad económica, ubicación, horarios, fotografías, descripción de productos y canales de contacto autorizados."],["Datos de cuenta: identificador de usuario, registros de acceso, preferencias y elementos necesarios para la autenticación."],["Información contractual: cotizaciones, pedidos, comprobantes, estado de pagos y comunicaciones relativas a los servicios."],["Información técnica: dirección IP, tipo de navegador, dispositivo, registros de seguridad y métricas de navegación, según las herramientas utilizadas."]]},{"h":"4. Formas de obtención"},{"p":["Los datos podrán obtenerse directamente del usuario al completar formularios, registrarse, solicitar una cotización, enviar mensajes o contratar servicios. También podrán generarse durante el uso de la plataforma mediante registros técnicos y tecnologías descritas en la política de cookies."]},{"p":["Cuando un anunciante suministre información de empleados, representantes o terceros, deberá contar con la autorización o fundamento legal necesario. Ofertas Bogotá podrá solicitar aclaraciones o retirar datos publicados sin autorización."]},{"h":"5. Uso de la información"},{"p":["La información se utilizará para administrar cuentas, gestionar anuncios, ejecutar servicios contratados, emitir documentos comerciales cuando corresponda, responder solicitudes y proteger la plataforma. También podrá utilizarse para elaborar estadísticas de funcionamiento y mejorar la experiencia de navegación."]},{"p":["Las comunicaciones promocionales y las finalidades opcionales se gestionarán de forma diferenciada de las comunicaciones necesarias para ejecutar un contrato. El usuario podrá retirar su autorización para recibir publicidad sin perder por ello el acceso a los servicios contratados."]},{"h":"6. Información pública y privada"},{"p":["Los datos comerciales autorizados para publicación, como nombre del negocio, barrio, localidad, descripción, fotografías y canales comerciales de contacto, podrán ser consultados por visitantes y eventualmente indexados por buscadores."]},{"p":["Las credenciales, documentos de identificación, datos de facturación y comunicaciones privadas no forman parte del perfil comercial público. El anunciante deberá revisar el contenido que autoriza publicar y evitar incluir información personal innecesaria. La retirada de un anuncio no garantiza la eliminación inmediata de copias conservadas por buscadores o terceros ajenos a la plataforma."]},{"h":"7. Pagos y seguridad financiera"},{"p":["Los datos de pago se tratarán únicamente en la medida necesaria para confirmar transacciones, gestionar obligaciones comerciales y atender reclamaciones. Cuando se utilicen pasarelas externas, el usuario deberá consultar las condiciones de su proveedor."]},{"p":["Ofertas Bogotá no solicitará contraseñas bancarias, códigos de autenticación ni claves de tarjetas por WhatsApp o correo. Los usuarios deberán abstenerse de enviar esa información por canales de atención."]},{"h":"8. Proveedores y destinatarios"},{"p":["Podrán intervenir proveedores de alojamiento, infraestructura, correo, soporte, analítica y pagos, exclusivamente cuando resulten necesarios y estén efectivamente habilitados. El acceso a los datos deberá limitarse a las finalidades autorizadas y a las obligaciones aplicables."]},{"p":["También podrá comunicarse información a autoridades competentes cuando exista un deber legal o requerimiento válido. Ofertas Bogotá no venderá datos personales como parte de su modelo de negocio."]},{"h":"9. Enlaces y comunicaciones externas"},{"p":["Los anuncios podrán contener enlaces a sitios de anunciantes o botones de contacto por WhatsApp. Al utilizar estos canales, el usuario podrá quedar sujeto a las políticas de privacidad de sus respectivos responsables. Ofertas Bogotá continuará respondiendo por el tratamiento que realice directamente o a través de sus encargados."]},{"h":"10. Conservación y eliminación"},{"p":["Los datos se conservarán durante el tiempo necesario para prestar los servicios, gestionar reclamaciones y cumplir obligaciones legales o contractuales. Cuando termine la finalidad y no exista obligación de conservación, se procederá a su eliminación, anonimización o restricción según corresponda."]},{"p":["La cancelación de una cuenta no implica la eliminación inmediata de documentos que deban conservarse por obligaciones legales. Los plazos específicos deberán corresponder a las prácticas reales de la plataforma."]},{"h":"11. Protección de la información"},{"p":["Ofertas Bogotá adoptará medidas técnicas, humanas y administrativas razonables para prevenir accesos no autorizados, pérdida, alteración o divulgación indebida de información. Estas medidas deberán revisarse conforme evolucione la plataforma."]},{"p":["Ningún sistema informático puede garantizar seguridad absoluta. El usuario deberá proteger sus credenciales y comunicar oportunamente cualquier actividad sospechosa, sin que ello exonere a Ofertas Bogotá de sus propias obligaciones."]},{"h":"12. Derechos y preferencias del usuario"},{"p":["El titular podrá conocer, actualizar y rectificar sus datos, solicitar prueba de autorización, conocer el uso dado a su información y solicitar su supresión o la revocación de la autorización cuando proceda. Podrá ejercer estos derechos gratuitamente conforme al procedimiento de la sección 4."]},{"h":"13. Menores y datos sensibles"},{"p":["La creación de cuentas comerciales está dirigida a mayores de edad o representantes autorizados. No se solicitarán datos sensibles innecesarios. Cualquier tratamiento excepcional de datos de menores o sensibles deberá cumplir las garantías legales descritas en la política de tratamiento de datos."]},{"h":"14. Cambios y contacto"},{"p":["Las actualizaciones se publicarán en el sitio web indicando su fecha de vigencia. Los cambios sustanciales se comunicarán a los titulares y se solicitará nueva autorización cuando legalmente corresponda. Las dudas podrán dirigirse a ",{"k":"correo_privacidad"},"."]}]},"datos":{"title":"Política de tratamiento de datos personales","blocks":[{"h":"1. Objeto y fundamento normativo"},{"p":["La presente política establece las reglas para la recolección, almacenamiento, uso, circulación y supresión de datos personales bajo responsabilidad de Ofertas Bogotá, de conformidad con la Ley 1581 de 2012, el Decreto 1074 de 2015 y las demás disposiciones aplicables en Colombia."]},{"h":"2. Responsable y área de atención"},{"p":["Responsable: ",{"k":"titular"},". Identificación: ",{"k":"nit"},". Dirección: ",{"k":"direccion"},". Correo: ",{"k":"correo_privacidad"},". Teléfono: 310 798 7275. Área o persona encargada de atender solicitudes: ",{"k":"cargo_datos"},". Fecha de entrada en vigencia: ",{"k":"fecha_vigencia"},"."]},{"h":"3. Definiciones"},{"ul":[["Titular: persona natural a quien corresponden los datos personales."],["Responsable: quien decide sobre la base de datos o el tratamiento."],["Encargado: quien realiza el tratamiento por cuenta del responsable."],["Autorización: consentimiento previo, expreso e informado del titular."],["Tratamiento: operación sobre datos personales, incluida su recolección, almacenamiento, uso, circulación o supresión."],["Dato sensible: información que afecta la intimidad o cuyo uso indebido puede generar discriminación."]]},{"h":"4. Principios del tratamiento"},{"p":["Ofertas Bogotá observará los principios de legalidad, finalidad, libertad, veracidad o calidad, transparencia, acceso y circulación restringida, seguridad y confidencialidad. La información deberá ser pertinente para la finalidad informada, mantenerse razonablemente actualizada y protegerse frente a accesos no autorizados."]},{"h":"5. Titulares y categorías de datos"},{"p":["La política comprende visitantes, usuarios registrados, representantes de negocios, anunciantes, clientes y personas que contacten a Ofertas Bogotá. Podrán tratarse datos identificativos, de contacto, comerciales, contractuales y técnicos en los términos de la política de privacidad. No se exigirá información ajena a las finalidades del servicio."]},{"h":"6. Finalidades del tratamiento"},{"ul":[["Crear, autenticar, administrar y recuperar cuentas de usuario."],["Gestionar perfiles comerciales, anuncios, ofertas y solicitudes de publicación."],["Elaborar cotizaciones, ejecutar contratos de publicidad, diseño y desarrollo web y gestionar entregables."],["Confirmar pagos, gestionar facturación y cumplir obligaciones contables y legales."],["Atender PQRS, solicitudes de soporte y ejercicio de derechos de los titulares."],["Prevenir fraude, investigar incidentes y mantener la seguridad de los sistemas."],["Medir el funcionamiento de la plataforma y mejorar sus funcionalidades, con las autorizaciones que correspondan."],["Enviar novedades, promociones y comunicaciones comerciales cuando exista autorización aplicable."]]},{"p":["La publicación de datos comerciales identificables requerirá informar al titular sobre su visibilidad pública. Las finalidades opcionales no deberán confundirse con las necesarias para ejecutar el servicio."]},{"h":"7. Autorización y prueba"},{"p":["Antes de recolectar datos se informará al titular sobre el responsable, las finalidades, los derechos y los canales de atención. Se obtendrá autorización previa, expresa e informada, salvo las excepciones legales. Podrá obtenerse por escrito, medios electrónicos o conductas inequívocas que permitan demostrarla; el silencio no constituye autorización."]},{"p":["Se conservará evidencia de la autorización, su fecha y la información presentada al titular. Los cambios sustanciales de finalidad requerirán nueva autorización cuando corresponda."]},{"h":"8. Datos sensibles y menores de edad"},{"p":["El titular no está obligado a autorizar el tratamiento de datos sensibles. Si excepcionalmente se requieren, se informará cuáles son, su finalidad y el carácter facultativo de la respuesta, y se obtendrá autorización explícita cuando proceda."]},{"p":["El tratamiento de datos de menores será excepcional, respetará su interés superior y sus derechos fundamentales, y observará las condiciones legales relativas a la autorización del representante y al derecho del menor a ser escuchado según su madurez."]},{"h":"9. Derechos de los titulares"},{"ul":[["Conocer, actualizar y rectificar sus datos personales."],["Solicitar prueba de la autorización otorgada, salvo excepción legal."],["Ser informado sobre el uso dado a sus datos."],["Acceder gratuitamente a los datos personales objeto de tratamiento en los términos legales."],["Solicitar la supresión de datos o revocar la autorización cuando proceda."],["Presentar quejas ante la Superintendencia de Industria y Comercio una vez agotado el trámite de consulta o reclamo correspondiente."]]},{"h":"10. Deberes del responsable"},{"p":["Ofertas Bogotá deberá garantizar el ejercicio de los derechos, conservar las autorizaciones, informar las finalidades, mantener la información en condiciones de seguridad, rectificar datos inexactos y tramitar consultas y reclamos. Deberá exigir a sus encargados el cumplimiento de las obligaciones aplicables y comunicar a la autoridad los incidentes cuando legalmente corresponda."]},{"h":"11. Presentación de solicitudes"},{"p":["El titular, su representante o persona legitimada podrá presentar una consulta o reclamo por ",{"k":"correo_privacidad"}," o ",{"k":"formulario_habilitado"},". Deberá indicar su identificación, descripción de la solicitud, medio de respuesta y documentos pertinentes. Se solicitará únicamente la acreditación de identidad necesaria para evitar divulgaciones indebidas."]},{"h":"12. Procedimiento de consultas"},{"p":["Las consultas sobre información personal se atenderán en un término máximo de diez (10) días hábiles contados desde su recepción. Si no fuera posible responder dentro de ese término, se informará al interesado antes de su vencimiento, explicando los motivos y señalando una fecha que no podrá superar los cinco (5) días hábiles siguientes al vencimiento inicial."]},{"h":"13. Procedimiento de reclamos"},{"p":["Los reclamos por corrección, actualización, supresión o presunto incumplimiento deberán incluir identificación del titular, descripción de los hechos, dirección de respuesta y documentos que se quieran hacer valer."]},{"p":["Si el reclamo está incompleto, se requerirá subsanación dentro de los cinco (5) días siguientes a su recepción. Transcurridos dos meses desde el requerimiento sin que se aporte la información solicitada, se entenderá desistido. Si quien recibe el reclamo no es competente, lo trasladará a quien corresponda en máximo dos (2) días hábiles e informará al interesado."]},{"p":["Una vez recibido el reclamo completo, se incluirá en la base de datos la leyenda «reclamo en trámite» y su motivo en un término no mayor a dos (2) días hábiles, manteniéndola hasta que se decida. El término máximo de respuesta será de quince (15) días hábiles contados desde el día siguiente a su recepción. Si no fuera posible responder, se informarán los motivos y la nueva fecha, que no podrá superar ocho (8) días hábiles adicionales."]},{"h":"14. Supresión y revocación"},{"p":["Las solicitudes de supresión o revocación serán evaluadas de acuerdo con las finalidades y obligaciones aplicables. No procederán respecto de datos cuya conservación sea necesaria por un deber legal o contractual vigente. En estos casos se informará al titular la razón y se limitará el uso a las finalidades que justifiquen su conservación."]},{"h":"15. Encargados y circulación de datos"},{"p":["Los proveedores que traten información por cuenta de Ofertas Bogotá deberán actuar bajo instrucciones, mantener confidencialidad y aplicar medidas de seguridad. Se limitará el acceso a los datos necesarios para ejecutar su función. Las comunicaciones a otros responsables deberán contar con el fundamento legal correspondiente."]},{"h":"16. Transferencias y transmisiones internacionales"},{"p":["Si la infraestructura o los proveedores implican tratamiento fuera de Colombia, se identificarán los países, destinatarios y finalidades, y se cumplirán los requisitos aplicables a transferencias y transmisiones internacionales. Cuando corresponda, se formalizarán contratos de transmisión y se obtendrán las autorizaciones exigidas."]},{"h":"17. Conservación y gestión de bases de datos"},{"p":["La información se conservará durante la vigencia de la relación y los periodos necesarios para atender obligaciones legales, contractuales y reclamaciones. Se establecerán plazos de conservación por categoría de datos, incluyendo cuentas, contratos, pagos, registros técnicos y solicitudes. Vencidos dichos plazos se aplicarán procedimientos de eliminación o anonimización, salvo obligación de conservación."]},{"h":"18. Seguridad e incidentes"},{"p":["Se establecerán controles de acceso, gestión de credenciales, protección de comunicaciones, respaldo y procedimientos de respuesta a incidentes adecuados al riesgo. Ante una posible vulneración se evaluará su alcance, se adoptarán medidas de contención y se realizarán las notificaciones exigidas por la normativa aplicable."]},{"h":"19. Vigencia y modificaciones"},{"p":["La política entrará en vigencia en ",{"k":"fecha_vigencia"}," y permanecerá disponible en www.ofertasbogota.lat. Las bases de datos tendrán vigencia mientras subsistan las finalidades legítimas y los deberes de conservación. Los cambios sustanciales serán informados antes de su implementación y se solicitará nueva autorización cuando corresponda."]}]},"cookies":{"title":"Política de cookies y tecnologías similares","blocks":[{"h":"1. Objeto"},{"p":["Esta política explica el uso de cookies y tecnologías similares en www.ofertasbogota.lat, sus finalidades y las opciones disponibles para administrarlas. Se aplica tanto a la navegación pública como al panel privado, según las tecnologías efectivamente instaladas."]},{"h":"2. Qué son las cookies"},{"p":["Las cookies son pequeños archivos que un sitio puede almacenar en el navegador. Otras tecnologías, como el almacenamiento local o identificadores de sesión, pueden cumplir funciones similares. Permiten mantener sesiones, recordar preferencias o medir el funcionamiento del sitio. Cuando permiten identificar a una persona, su tratamiento se somete también a la normativa de protección de datos."]},{"h":"3. Cookies necesarias"},{"p":["Son las utilizadas para funcionalidades esenciales, como autenticación, continuidad de sesión, seguridad y gestión de preferencias de privacidad. Su bloqueo puede impedir el acceso al panel del cliente o afectar operaciones básicas. Se informará sobre su utilización y el fundamento aplicable al tratamiento de datos que impliquen."]},{"h":"4. Cookies de preferencias"},{"p":["Cuando estén habilitadas, permiten recordar opciones como ubicación seleccionada, filtros o configuraciones de navegación. No se utilizarán para finalidades distintas de las informadas sin cumplir los requisitos de autorización correspondientes."]},{"h":"5. Cookies analíticas"},{"p":["Si se implementan, permitirán medir visitas, rendimiento, páginas consultadas y errores de funcionamiento. Se procurará minimizar la identificación de usuarios y utilizar información agregada cuando sea posible. Su activación estará sujeta a las preferencias y autorizaciones aplicables."]},{"h":"6. Cookies publicitarias"},{"p":["Si se incorporan herramientas de medición de campañas, atribución o personalización publicitaria, se informará sobre sus proveedores, finalidades y duración. Las tecnologías opcionales que requieran autorización no se activarán antes de obtenerla. La publicación de anuncios en el directorio no implica por sí misma el uso de cookies publicitarias."]},{"h":"7. Cookies propias y de terceros"},{"p":["Las cookies propias son administradas por el sitio. Las de terceros pueden proceder de servicios externos integrados, como analítica, contenidos o pagos. Ofertas Bogotá identificará los proveedores realmente utilizados y facilitará información sobre sus políticas. No se presume que exista una integración por el solo hecho de mencionarla en esta política."]},{"h":"8. Duración y almacenamiento"},{"p":["Las cookies de sesión pueden desaparecer al finalizar la sesión o cerrar el navegador; las persistentes permanecen durante un periodo definido o hasta que el usuario las elimine. La duración concreta de cada tecnología deberá indicarse en el inventario actualizado."]},{"h":"9. Consentimiento y preferencias"},{"p":["Cuando se requiera autorización, el usuario podrá aceptar, rechazar o configurar las categorías opcionales mediante ",{"k":"enlace_preferencias"},". El rechazo de tecnologías opcionales no impedirá utilizar las funciones esenciales del sitio. Se conservará evidencia de las preferencias cuando corresponda y se permitirá modificarlas o retirarlas de manera accesible."]},{"h":"10. Administración desde el navegador"},{"p":["El usuario podrá consultar, eliminar o bloquear cookies mediante la configuración de su navegador. La eliminación de cookies puede cerrar sesiones y restablecer preferencias. Bloquear cookies necesarias puede afectar el funcionamiento de la cuenta. La configuración del navegador complementa, pero no reemplaza, los mecanismos de consentimiento que deba ofrecer la plataforma."]},{"h":"11. Inventario de tecnologías"},{"p":["Antes de publicar esta política deberá completarse el inventario real con nombre de cada cookie o tecnología, proveedor, dominio, finalidad, categoría y duración. ",{"k":"nota_inventario"},". No se declararán herramientas que no estén instaladas."]},{"h":"12. Actualizaciones y contacto"},{"p":["La política se actualizará cuando cambien las tecnologías o sus finalidades. Cuando corresponda, se solicitará nuevamente autorización. Las consultas podrán dirigirse a ",{"k":"correo_privacidad"}," y los derechos sobre datos personales se ejercerán conforme a la sección 4."]}]},"pqrs":{"title":"PQRS: peticiones, quejas, reclamos y sugerencias","blocks":[{"h":"1. Objeto y alcance"},{"p":["Ofertas Bogotá establece un procedimiento de atención para recibir, registrar, analizar y responder solicitudes de visitantes, usuarios registrados, anunciantes y clientes. El propósito es facilitar soluciones oportunas, identificar oportunidades de mejora y garantizar el ejercicio de los derechos que correspondan."]},{"p":["La política comprende publicidad digital, diseño gráfico, desarrollo web, cuentas, facturación, funcionamiento de la plataforma y reportes sobre publicaciones de terceros. No limita los mecanismos legales de reclamación ni el acceso a autoridades competentes."]},{"h":"2. Clasificación de solicitudes"},{"ul":[["Petición: solicitud de información, documentos, orientación o realización de una gestión."],["Queja: manifestación de inconformidad con la atención, conducta o funcionamiento del servicio."],["Reclamo: solicitud de solución frente a un incumplimiento, cobro, defecto o afectación de derechos."],["Sugerencia: propuesta para mejorar los servicios, funcionalidades o procesos."],["Reporte: aviso sobre anuncios engañosos, fraude, contenido prohibido, suplantación o incidentes de seguridad."]]},{"p":["La clasificación interna no reducirá los derechos del solicitante ni modificará los plazos legales aplicables a su solicitud."]},{"h":"3. Canales oficiales de atención"},{"p":["Las solicitudes podrán presentarse mediante www.ofertasbogota.lat, ",{"k":"form_pqrs"},", ",{"k":"correo_atencion"}," o WhatsApp 310 798 7275. El horario de atención será ",{"k":"horario"},". La recepción electrónica fuera del horario no alterará los términos legales que resulten aplicables."]},{"h":"4. Información para presentar una solicitud"},{"p":["Se recomienda indicar nombre, medio de contacto, descripción clara de los hechos, solución solicitada y, cuando corresponda, número de anuncio, pedido, cotización o comprobante. Podrán adjuntarse capturas y documentos pertinentes. No se deberán enviar contraseñas, códigos bancarios ni datos personales de terceros innecesarios."]},{"p":["La falta de un número de pedido no impedirá presentar una reclamación cuando pueda identificarse el servicio por otros medios. Se solicitará información adicional únicamente cuando resulte necesaria para resolver el caso."]},{"h":"5. Recepción y registro"},{"p":["Ofertas Bogotá asignará un identificador de seguimiento o entregará constancia de recepción mediante el canal habilitado. Se registrarán fecha de ingreso, tipo de solicitud, descripción y medio de respuesta. ",{"k":"nota_radicacion"},"."]},{"h":"6. Evaluación y gestión"},{"p":["La solicitud se remitirá al responsable del servicio correspondiente. Se revisarán los antecedentes, condiciones contratadas, comprobantes y evidencias disponibles. Si se requieren aclaraciones, se informará al solicitante respetando los términos legales. La respuesta deberá abordar los hechos y la solución solicitada de forma clara y motivada."]},{"h":"7. Términos de respuesta"},{"p":["Las reclamaciones directas de consumidores sujetas al artículo 58 de la Ley 1480 de 2011 se responderán dentro de los quince (15) días hábiles siguientes a su recepción, con los soportes que correspondan. Las consultas y reclamos de datos personales se atenderán conforme a los términos de diez (10) y quince (15) días hábiles, respectivamente, y las reglas de prórroga de la sección 4."]},{"p":["Las peticiones sometidas al régimen de derecho de petición se atenderán según la Ley 1755 de 2015 cuando resulte aplicable, incluyendo los términos especiales para información, documentos y consultas según su naturaleza. Para solicitudes ordinarias sin término legal especial se propone un plazo interno de quince (15) días hábiles ",{"k":"nota_compromiso"},". Ningún plazo interno ampliará un término legal obligatorio."]},{"h":"8. Reclamos por publicidad y anuncios"},{"p":["Los clientes podrán reportar anuncios no publicados, errores de ubicación, duración incorrecta, problemas de visualización o diferencias frente al plan contratado. Se verificará la orden y el estado de publicación y se adoptarán las correcciones, compensaciones o devoluciones que correspondan."]},{"p":["Los visitantes podrán reportar contenido engañoso o ilegal. Ofertas Bogotá evaluará la publicación y podrá solicitar aclaraciones, suspenderla o retirarla según los términos y condiciones. La resolución de una compra realizada directamente con un anunciante dependerá de las obligaciones de las partes, sin excluir las responsabilidades legales de la plataforma."]},{"h":"9. Reclamos por diseño gráfico y desarrollo web"},{"p":["Se revisarán la cotización aceptada, alcance, entregables, plazos y modificaciones acordadas. Cuando exista un incumplimiento atribuible a Ofertas Bogotá se evaluarán las correcciones y demás remedios legales o contractuales. Las solicitudes de funcionalidades adicionales se tratarán como cambios de alcance únicamente cuando realmente excedan lo contratado."]},{"h":"10. Pagos, cancelaciones y devoluciones"},{"p":["Las solicitudes relacionadas con cobros duplicados, pagos no reconocidos, cancelaciones, retracto o devolución serán revisadas conforme al contrato y a la legislación aplicable. Se informará la decisión, sus motivos y, cuando proceda, el mecanismo y plazo de devolución. El usuario podrá ejercer los derechos legales sin que se le impongan requisitos adicionales injustificados."]},{"h":"11. Reportes de seguridad y fraude"},{"p":["Los reportes de accesos no autorizados, suplantación o vulnerabilidades deberán remitirse a ",{"k":"canal_seguridad"},". Se dará prioridad a los casos que representen un riesgo para las cuentas o datos personales. Se podrán aplicar medidas preventivas proporcionales mientras se verifica el incidente y se informará al afectado cuando corresponda."]},{"h":"12. Respuesta, seguimiento y cierre"},{"p":["La respuesta se enviará por el medio indicado por el solicitante, incluyendo el resultado, las razones de la decisión y las acciones previstas cuando procedan. Se conservará constancia de la recepción y respuesta conforme a los plazos de conservación aplicables. El usuario podrá solicitar revisión aportando información adicional, sin perjuicio de los mecanismos legales disponibles."]},{"h":"13. Confidencialidad y protección de datos"},{"p":["Los datos y documentos aportados se utilizarán para gestionar la solicitud, acreditar actuaciones y cumplir obligaciones legales. Su acceso estará restringido a las personas autorizadas. Las solicitudes sobre datos personales se tramitarán conforme a la política específica, aunque hayan ingresado por el canal general de PQRS."]},{"h":"14. Autoridades y mecanismos externos"},{"p":["Cuando corresponda, el usuario podrá acudir a la Superintendencia de Industria y Comercio (www.sic.gov.co), a mecanismos de conciliación o a las autoridades judiciales competentes. Para quejas sobre tratamiento de datos ante la SIC deberá agotarse previamente el trámite correspondiente ante el responsable o encargado. El procedimiento interno no impone renuncias a los derechos del consumidor."]},{"h":"15. Mejora continua y vigencia"},{"p":["Ofertas Bogotá revisará las solicitudes recibidas para identificar fallas recurrentes, mejorar la atención y fortalecer sus servicios. Esta política entrará en vigencia el ",{"k":"fecha_vigencia"}," y estará disponible en el sitio web. Los canales y procedimientos deberán mantenerse actualizados."]}]},"colombia":{"title":"Hecho en Colombia","blocks":[{"p":["Ofertas Bogotá es una iniciativa digital colombiana que nace para apoyar a los negocios locales de Bogotá y la Sabana. Creemos en el talento de nuestros emprendedores y en las oportunidades que brinda la transformación digital."]},{"h":"Copyright"},{"p":["© 2026 Ofertas Bogotá. Todos los derechos reservados."]}]}}};
